const items = $input.all();
const rows = items.map(i => i.json);
const now = new Date();
const monthName = now.toLocaleString('en', { month: 'long', year: 'numeric' });

const tableRows = rows.map(r => {
  const cols = Object.values(r).map(v => `<td style="border:1px solid #ddd;padding:8px;">${v}</td>`).join('');
  return `<tr>${cols}</tr>`;
}).join('');
const headers = Object.keys(rows[0] || {}).map(h => `<th style="border:1px solid #ddd;padding:8px;background:#4CAF50;color:white;">${h}</th>`).join('');

const totalRows = rows.length;
const numericCols = Object.keys(rows[0] || {}).filter(k => !isNaN(parseFloat(rows[0][k])));
const summaries = numericCols.map(col => {
  const vals = rows.map(r => parseFloat(r[col]) || 0);
  const sum = vals.reduce((a, b) => a + b, 0);
  return `<p><strong>${col}:</strong> Total = ${sum.toFixed(2)}, Avg = ${(sum / vals.length).toFixed(2)}</p>`;
}).join('');

const chartData = JSON.stringify({
  labels: rows.slice(0, 10).map((r, i) => Object.values(r)[0] || `Row ${i}`),
  values: rows.slice(0, 10).map(r => parseFloat(Object.values(r)[1]) || 0)
});

const html = `<!DOCTYPE html><html><head><style>
  body { font-family: Arial, sans-serif; margin: 40px; color: #333; }
  h1 { color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; }
  table { border-collapse: collapse; width: 100%; margin: 20px 0; }
  .summary { background: #f8f9fa; padding: 20px; border-radius: 8px; margin: 20px 0; }
  .footer { color: #999; font-size: 12px; margin-top: 40px; border-top: 1px solid #eee; padding-top: 10px; }
</style></head><body>
  <h1>Monthly Report - ${monthName}</h1>
  <div class="summary"><h3>Summary</h3><p>Total Records: ${totalRows}</p>${summaries}</div>
  <h3>Data Table</h3>
  <table><thead><tr>${headers}</tr></thead><tbody>${tableRows}</tbody></table>
  <div class="footer">Generated automatically on ${now.toISOString()}</div>
</body></html>`;

return [{ json: { html, monthName, totalRows, generated: now.toISOString() } }];

